    "source": "def lcs(X: str, Y: str) -> tuple[int, str]:\n    \"\"\"LCS DP + reconstruct — complete Python reference.\"\"\"\n    m = len(X)\n    n = len(Y)\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n    for i in range(m + 1):\n        dp[i][0] = 0\n    for j in range(n + 1):\n        dp[0][j] = 0\n    for i in range(1, m + 1):\n        for j in range(1, n + 1):\n            if X[i - 1] == Y[j - 1]:\n                dp[i][j] = dp[i - 1][j - 1] + 1\n            else:\n                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\n    i = m\n    j = n\n    chars: list[str] = []\n    while i > 0 and j > 0:\n        if X[i - 1] == Y[j - 1]:\n            chars.append(X[i - 1])\n            i -= 1\n            j -= 1\n        elif dp[i - 1][j] >= dp[i][j - 1]:\n            i -= 1\n        else:\n            j -= 1\n    return dp[m][n], \"\".join(reversed(chars))\n",
