    "source": "// LCS DP + reconstruct — complete C++ reference.\n#include <algorithm>\n#include <string>\n#include <vector>\n\nstruct LcsResult {\n  int length;\n  std::string sequence;\n};\n\nLcsResult lcs(const std::string& X, const std::string& Y) {\n  const int m = static_cast<int>(X.size());\n  const int n = static_cast<int>(Y.size());\n  std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));\n  for (int i = 0; i <= m; i++) dp[i][0] = 0;\n  for (int j = 0; j <= n; j++) dp[0][j] = 0;\n  for (int i = 1; i <= m; i++) {\n    for (int j = 1; j <= n; j++) {\n      if (X[i - 1] == Y[j - 1]) {\n        dp[i][j] = dp[i - 1][j - 1] + 1;\n      } else {\n        dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);\n      }\n    }\n  }\n  int i = m;\n  int j = n;\n  std::string chars;\n  while (i > 0 && j > 0) {\n    if (X[i - 1] == Y[j - 1]) {\n      chars.push_back(X[i - 1]);\n      i--;\n      j--;\n    } else if (dp[i - 1][j] >= dp[i][j - 1]) {\n      i--;\n    } else {\n      j--;\n    }\n  }\n  return {dp[m][n], std::string(chars.rbegin(), chars.rend())};\n}\n",
