    "source": "/// LCS DP + reconstruct — complete Rust reference.\npub fn lcs(x_str: &str, y_str: &str) -> (usize, String) {\n    let x: Vec<char> = x_str.chars().collect();\n    let y: Vec<char> = y_str.chars().collect();\n    let (m, n) = (x.len(), y.len());\n    let mut dp = vec![vec![0usize; n + 1]; m + 1];\n    for i in 0..=m {\n        dp[i][0] = 0;\n    }\n    for j in 0..=n {\n        dp[0][j] = 0;\n    }\n    for i in 1..=m {\n        for j in 1..=n {\n            if x[i - 1] == y[j - 1] {\n                dp[i][j] = dp[i - 1][j - 1] + 1;\n            } else {\n                dp[i][j] = dp[i - 1][j].max(dp[i][j - 1]);\n            }\n        }\n    }\n    let mut i = m;\n    let mut j = n;\n    let mut chars: Vec<char> = Vec::new();\n    while i > 0 && j > 0 {\n        if x[i - 1] == y[j - 1] {\n            chars.push(x[i - 1]);\n            i -= 1;\n            j -= 1;\n        } else if dp[i - 1][j] >= dp[i][j - 1] {\n            i -= 1;\n        } else {\n            j -= 1;\n        }\n    }\n    (dp[m][n], chars.iter().rev().collect())\n}\n",
