    "source": "// LCS DP + reconstruct — complete Go reference.\npackage algorithms\n\nimport \"slices\"\n\n// lcs returns the LCS length of X and Y and one longest common subsequence.\nfunc lcs(X, Y string) (int, string) {\n\tm := len(X)\n\tn := len(Y)\n\tdp := make([][]int, m+1)\n\tfor i := range dp {\n\t\tdp[i] = make([]int, n+1)\n\t}\n\tfor i := 0; i <= m; i++ {\n\t\tdp[i][0] = 0\n\t}\n\tfor j := 0; j <= n; j++ {\n\t\tdp[0][j] = 0\n\t}\n\tfor i := 1; i <= m; i++ {\n\t\tfor j := 1; j <= n; j++ {\n\t\t\tif X[i-1] == Y[j-1] {\n\t\t\t\tdp[i][j] = dp[i-1][j-1] + 1\n\t\t\t} else {\n\t\t\t\tdp[i][j] = max(dp[i-1][j], dp[i][j-1])\n\t\t\t}\n\t\t}\n\t}\n\ti := m\n\tj := n\n\tchars := []byte{}\n\tfor i > 0 && j > 0 {\n\t\tif X[i-1] == Y[j-1] {\n\t\t\tchars = append(chars, X[i-1])\n\t\t\ti--\n\t\t\tj--\n\t\t} else if dp[i-1][j] >= dp[i][j-1] {\n\t\t\ti--\n\t\t} else {\n\t\t\tj--\n\t\t}\n\t}\n\tslices.Reverse(chars)\n\treturn dp[m][n], string(chars)\n}\n",
